import {gCirclePoint} from './chart.mjs';
import {drawPerformanceReport} from './report-chart.mjs';
import {DeviceSimulator,SimulatorAdapter,MODES} from './engine.mjs';
import {sliceSamples,roadProfile} from './analytics.mjs';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const KEY='gnss-prototype-v2';let saved={};try{saved=JSON.parse(localStorage.getItem(KEY)||'{}');}catch{$('#storage-error').textContent='Локальное хранилище недоступно. Новые записи останутся только до закрытия страницы.';}
const device=new DeviceSimulator(saved),adapter=new SimulatorAdapter(device);
let state=adapter.state(),page='live',historyTab='auto',filter='all',detailId=null,selectedSegment=null,chartAxis='time',cursor=null,visibleSeries={speed:true,longitudinal:true,height:true},renderKey='',lastDetailKey='',toastTimer;
const announcedMilestones=new Set(),renderedEventIds=new Set();
const carName=id=>state.device.cars.find(c=>c.id===id)?.name||'Без автомобиля';
const modeName=m=>m.id==='custom'?`${m.from}–${m.to} км/ч`:m.name;
const fmt=v=>Number(v||0).toFixed(2),signed=v=>(v>=0?'+':'')+fmt(v)+' g';
const duration=s=>`${Math.floor(s/60)}:${String(Math.floor(s%60)).padStart(2,'0')}`;
const date=t=>new Date(t).toLocaleString('ru-RU',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'});
function toast(s){$('#toast').textContent=s;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').textContent='',4000);}
function persist(){try{localStorage.setItem(KEY,JSON.stringify(device.export()));}catch{$('#storage-error').textContent='Не удалось сохранить записи в браузере. Они доступны до закрытия страницы.';}}
async function command(type,payload={}){try{await adapter.command(type,payload);persist();return true;}catch(e){toast(e.message);return false;}}
const active=()=>['conditions','waiting','running'].includes(state.device.attempt?.phase);
const locked=()=>!!state.device.trip||active();
function navigate(next){page=next;detailId=null;renderKey='';render();}
function recordById(){return [...(state.device.autoSessions||[]),...state.device.runs,...state.device.trips].find(r=>r.id===detailId);}
function detailContext(){const record=recordById();if(!record)return null;if(record.segments){const segment=record.segments.find(s=>s.recordId===selectedSegment);const samples=segment?sliceSamples(record.samples,segment.start,segment.end):record.samples;return {record,session:record,segment,samples};}if(record.auto&&record.sessionId){const session=(state.device.autoSessions||[]).find(s=>s.sessionId===record.sessionId),segment=session?.segments.find(s=>s.recordId===record.id);return {record,session,segment,samples:session&&segment?sliceSamples(session.samples,segment.start,segment.end):record.samples||[]};}return {record,session:null,segment:null,samples:record.samples||[]};}
function carOptions(selected,all=false){return `${all?'<option value="all">Все автомобили</option>':''}<option value="none" ${selected==='none'?'selected':''}>Без автомобиля</option>`+state.device.cars.map(c=>`<option value="${c.id}" ${selected===c.id?'selected':''}>${esc(c.name)}</option>`).join('');}
function gMarkup(id){return `<div class="g-wrap"><canvas id="${id}" aria-label="Круг перегрузок ±1 g"></canvas><span class="g-right" data-g-lat>—</span><span class="g-bottom" data-g-long>—</span></div>`;}
function liveHTML(){const d=state.device;return `<div class="stack live-page"><div class="top-choice"><button id="choose-car"><small>Автомобиль</small><span>${esc(carName(d.carId))} ▾</span></button><button id="choose-mode"><small>Режим замера</small><span>${esc(modeName(d.mode))} ▾</span></button></div><section class="panel dashboard"><div class="status"><span id="gnss-state"></span><span id="sat-state"></span><span id="link-state"></span></div><div id="event-card" class="event-card" aria-live="polite"></div><div class="gauge-grid"><div class="speed-dial" aria-label="Текущая скорость">${speedometerMarkup()}<div class="speed-center"><span id="speed-value">—</span><small>км/ч</small></div></div><div class="g-force">${gMarkup('live-g')}</div></div><div class="run-meta"><div id="recording-state" class="recording-state"><i></i><div><small>Запись</small><strong id="session-clock">Выключена</strong></div></div><div class="run-time"><small>Таймер заезда</small><strong><span id="time-value">0.00</span> с</strong></div><div class="phase compact-phase"><small>Фаза</small><strong id="phase-title"></strong><span id="phase-hint"></span></div></div><div class="events-head"><span>Последние события</span><small id="event-count"></small></div><div id="event-feed" class="event-feed" aria-label="Последние контрольные точки" aria-live="polite" aria-relevant="additions"></div><div class="progress"><div id="run-progress"></div></div><div id="run-actions" class="actions primary-actions"></div><div class="trip row between legacy-trip"><div><p id="trip-title">Запись поездки</p><small id="trip-clock">Выключена</small></div><button id="trip-toggle">Начать запись</button></div></section></div>`;}
function historyHTML(){const d=state.device,records=(historyTab==='auto'?(d.autoSessions||[]):d.runs).filter(r=>filter==='all'||(r.carId||'none')===filter);const card=r=>{const auto=!!r.segments,items=auto?r.segments.slice(0,4).map(s=>'<span>'+esc(s.label)+' · '+fmt(s.elapsed)+' с</span>').join(''):'';const title=auto?'Авто':modeName(r.mode),time=auto?fmt(r.duration):fmt(r.elapsed),distance=auto?Math.round(r.distance||0)+' м':'';return '<button class="record '+(r.valid?'':'invalid')+'" data-detail="'+r.id+'"><div class="row between"><span>'+esc(title)+'</span><strong>'+time+' с</strong></div><small>'+esc(carName(r.carId))+' · '+date(r.createdAt)+(distance?' · '+distance:'')+'</small><span class="tag '+(r.valid?'':'invalid')+'">'+(r.valid?'Достоверно':esc((r.reasons||[]).join(' · ')))+'</span>'+ (items?'<div class="record-segments">'+items+'</div>':'')+'</button>';};return '<div class="stack history-page"><div><p class="eyebrow">Локальные записи</p><h1>История</h1></div><div class="tabs history-tabs"><button data-history="auto" aria-selected="'+(historyTab==='auto')+'">Авто · '+(d.autoSessions||[]).length+'</button><button data-history="runs" aria-selected="'+(historyTab==='runs')+'">Замеры · '+d.runs.length+'</button></div><label>Автомобиль<select id="history-filter">'+carOptions(filter,true)+'</select></label>'+ (records.length?records.map(card).join(''):'<div class="panel empty">Здесь появятся завершённые автозаезды и отдельные замеры.</div>')+'</div>';}
function detailHTML(){const c=detailContext();if(!c)return '<p>Запись пока не загружена.</p>';const r=c.record,s=c.session,g=c.segment,ss=c.samples,m=g?.metrics||s||r,profile=roadProfile(ss),hasAltitude=profile.hasAltitude,slopeConfirmed=profile.available,title=g?.label||(s?'Авто':'Замер'),time=g?.elapsed??s?.duration??r.elapsed??0,segments=s?.segments||[],distanceReady=ss.length>1&&ss.every(x=>Number.isFinite(x.distanceM))&&ss.at(-1).distanceM>ss[0].distanceM;const card=(x,y,z)=>'<div><small>'+x+'</small><strong>'+y+(z?' '+z:'')+'</strong></div>';const choose=s?'<div class="segment-picker"><button data-segment="" class="'+(!g?'selected':'')+'">Весь заезд</button>'+segments.map(x=>'<button data-segment="'+x.recordId+'" class="'+(g?.recordId===x.recordId?'selected':'')+'">'+esc(x.label)+'</button>').join('')+'</div>':'';const series=[['speed','Скорость','км/ч','speed'],['longitudinal','Ускорение','g','longitudinal']].concat(hasAltitude?[['height','Высота','м','height']]:[]);const legend='<div class="chart-legend">'+series.map(x=>'<button data-series-toggle="'+x[3]+'" aria-pressed="'+!!visibleSeries[x[3]]+'"><i class="series-'+x[3]+'"></i>'+x[1]+' <small>'+x[2]+'</small></button>').join('')+'<span class="legend-slope"><i></i>Уклон <small>%</small></span></div>';const altitudeCards=hasAltitude?card('Высота старта',fmt(profile.startAltitudeM),'м')+card('Высота финиша',fmt(profile.endAltitudeM),'м')+card('Перепад',fmt(profile.deltaAltitudeM),'м')+(slopeConfirmed?card('Уклон',fmt(profile.averageSlopePercent),'%')+card('Подъём',fmt(profile.maxUphillPercent),'%')+card('Спуск',fmt(profile.maxDownhillPercent),'%'):card('Уклон','Сбор данных')):card('Уклон','Недоступен');return '<div class="stack report-page"><button class="quiet" id="back-history">‹ История</button><section class="panel stack report-head"><div><p class="eyebrow">'+esc(title)+'</p><h1>'+fmt(time)+' с</h1><p class="muted">'+esc(carName(r.carId))+' · '+date(r.createdAt)+'</p></div><p class="'+(r.valid?'':'bad')+'">'+(r.valid?'Достоверный результат':esc((r.reasons||[]).join(' · ')))+'</p><div class="summary-grid">'+card('Дистанция',Math.round(m.distanceM??r.distance??0),'м')+card('Максимум',fmt(m.maxSpeed??0),'км/ч')+card('Ускорение',signed(m.peakAcceleration??0))+card('Торможение',signed(m.peakBraking??0))+altitudeCards+'</div>'+choose+'</section><section class="panel stack report-charts"><div class="report-chart-head"><h2>График заезда</h2><div class="axis-switch"><span>Ось X</span><button data-axis="time" class="'+(chartAxis==='time'?'selected':'')+'">Время</button><button data-axis="distance" '+(!distanceReady?'disabled title="Дистанция не записывалась"':'')+' class="'+(chartAxis==='distance'?'selected':'')+'">Расстояние</button></div></div>'+legend+'<canvas id="performance-chart" class="performance-chart" tabindex="0" aria-label="Скорость, ускорение и высота. Нажмите или используйте стрелки для просмотра значений." aria-describedby="chart-cursor"></canvas>'+'<canvas id="slope-chart" class="slope-chart '+(hasAltitude?'':'is-hidden')+'" tabindex="0" aria-label="Локальный уклон. Нажмите или используйте стрелки для просмотра значений." aria-describedby="chart-cursor"></canvas>'+(!hasAltitude?'<p class="slope-unavailable">Высота и уклон не записывались</p>':'')+'<div id="chart-cursor" class="chart-cursor" aria-live="polite"><strong id="cursor-time">Коснитесь графика</strong><span id="cursor-distance"></span><span id="cursor-speed">Скорость —</span><span id="cursor-long">Ускорение —</span><span id="cursor-alt">Высота —</span><span id="cursor-slope">Уклон —</span></div><p id="cursor-gap" class="bad"></p></section><details class="panel"><summary>Качество данных</summary><dl class="diagnostics"><dt>Образцы</dt><dd>'+ss.length+'</dd><dt>Высота</dt><dd>'+(hasAltitude?'Доступна':'Не записывалась')+'</dd><dt>Источник</dt><dd>Симуляция</dd></dl></details></div>';} 
function deviceHTML(){const d=state.device;return `<div class="stack"><div><p class="eyebrow">Автономный прибор</p><h1>Устройство</h1></div><section class="panel stack"><div class="row"><div class="device-icon">G</div><div><h2>GNSS Meter S3</h2><p id="device-link" class="muted"></p></div></div><button id="connect-toggle">${state.connected?'Отключиться':'Подключиться'}</button><p class="hint">Телефон управляет прибором; замер и запись продолжаются независимо от связи.</p></section><section class="panel stack"><h2>Настройки</h2><label>Яркость дисплея <output id="brightness-value">${d.settings.brightness}%</output><input id="brightness" type="range" min="0" max="100" value="${d.settings.brightness}"></label><label class="switch">Звук пищалки<input id="sound" type="checkbox" ${d.settings.sound?'checked':''}></label><div class="divider"></div><h3>Калибровка IMU</h3><p class="hint">Остановитесь и оставьте прибор неподвижным.</p><p id="calibration-status"></p><button id="calibrate">Начать калибровку</button><small id="command-state"></small></section><section class="panel"><details><summary>Подробная диагностика</summary><dl class="diagnostics"><dt>GNSS</dt><dd id="diag-gnss"></dd><dt>Частота GNSS</dt><dd>20 Гц</dd><dt>Частота IMU</dt><dd>200 Гц (модель)</dd><dt>Sequence</dt><dd id="diag-seq"></dd><dt>Возраст образца</dt><dd id="diag-age"></dd><dt>Поток</dt><dd id="diag-gap"></dd></dl></details></section></div>`;}
function render(force=false){document.body.classList.add('app-theme');document.body.classList.toggle('live-theme',page==='live'&&!detailId);const d=state.device;const key=[page,detailId,historyTab,filter,d.cars.map(c=>c.name).join('|'),d.runs.length,d.trips.length,(d.autoSessions||[]).length,selectedSegment,chartAxis].join(':');if(force||key!==renderKey){renderKey=key;$('#page').innerHTML=detailId?detailHTML():page==='live'?liveHTML():page==='history'?historyHTML():deviceHTML();bindPage();}document.querySelectorAll('[data-nav]').forEach(b=>b.setAttribute('aria-current',b.dataset.nav===page?'page':'false'));$('#connection-banner').innerHTML=state.connected?'':'<div class="notice">Связь потеряна. Показан последний полученный кадр. Прибор продолжает работу; результат загрузится после подключения.</div>';if(detailId){if(force||key!==lastDetailKey){lastDetailKey=key;updateDetail();}}else if(page==='live')((d.attempt?.mode||d.mode).auto?(updateAutoLive(),updateCockpit()):updateLive());else if(page==='device')updateDevice();if(page==='live'&&!detailId)updateInstruments();}
function updateLive(){const d=state.device,a=d.attempt,phase=a?.phase||'idle',s=d.sample;$('.dashboard').classList.toggle('measuring',!!a);$('#speed-value').textContent=s?s.speed.toFixed(1):'—';$('#time-value').textContent=fmt(a?.elapsed);$('#gnss-state').textContent=d.gnss?'GNSS готов':'GNSS недостоверен';$('#gnss-state').classList.toggle('bad',!d.gnss);$('#sat-state').textContent=`SV ${s?.satellites??'—'}`;$('#link-state').textContent=!state.connected?'Устаревший кадр':d.gap?'Нет данных':'Связь установлена';const milestone=a?.milestones?.at(-1),milestoneText=milestone?`${milestone.speed} км/ч · ${fmt(milestone.elapsed)} с`:'';const runningHint=a?.reasons.length?a.reasons.join(' · '):(milestoneText||(a?.mode.distance?`${a.distance.toFixed(0)} / ${a.mode.distance.toFixed(0)} м`:'Старт и финиш определяет прибор'));const text=phase==='conditions'?[ 'Ожидание условий',a.mode.brake?'Наберите скорость выше 100 км/ч':a.mode.from===0?'Остановитесь перед стартом':`Снизьте скорость ниже ${a.mode.from} км/ч`]:phase==='waiting'?['Ожидание старта',a.mode.brake?'Начните торможение':a.mode.from===0?'Начните движение':`Достигните ${a.mode.from} км/ч`]:phase==='running'?['Замер идёт',runningHint]:phase==='result'?['Результат сохранён',a.valid?(milestoneText?`Отметки: ${a.milestones.map(item=>`${item.speed} км/ч · ${fmt(item.elapsed)} с`).join(' · ')}`:'Достоверный результат'):a.reasons.join(' · ')]:[d.gnss&&!d.gap?'Готов к подготовке':'Не готов',d.gnss&&!d.gap?'Выберите режим и подготовьте попытку':'Нужны свежие достоверные данные GNSS'];$('#phase-title').textContent=text[0];$('#phase-hint').textContent=text[1];$('#phase-hint').classList.toggle('bad',!!a?.reasons.length);const actionKey=`${phase}-${state.connected}-${state.pending}-${d.gnss}-${d.gap}`;const box=$('#run-actions');if(box.dataset.key!==actionKey){box.dataset.key=actionKey;const disabled=!state.connected||state.pending?'disabled':'';box.innerHTML=phase==='result'?`<button class="primary" data-action="arm" ${disabled}>Повторить</button><button data-action="detail">Подробнее</button><button data-action="dismiss" ${disabled}>К прибору</button>`:active()?`<button class="danger" data-action="cancel" ${disabled}>${phase==='running'?'Прервать попытку':'Отменить ожидание'}</button>`:`<button class="primary" data-action="arm" ${disabled||(!d.gnss||d.gap?'disabled':'')}>${state.pending?'Подтверждение…':'Готов к замеру'}</button>`;box.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>b.dataset.action==='detail'?openDetail(a.id):command(b.dataset.action));}
$('#choose-car').disabled=locked()||!state.connected||state.pending;$('#choose-mode').disabled=active()||!state.connected||state.pending;$('#choose-car span').textContent=carName(d.carId)+' ▾';$('#choose-mode span').textContent=modeName(d.mode)+' ▾';$('#trip-title').textContent=d.trip?'Поездка записывается':'Запись поездки';$('#trip-clock').textContent=d.trip?duration(d.trip.duration):'Выключена';$('#trip-toggle').textContent=d.trip?'Остановить запись':'Начать запись';$('#trip-toggle').disabled=!state.connected||state.pending;$('#run-progress').style.width=(phase==='result'?100:phase==='running'?Math.min(100,a.mode.distance?a.distance/a.mode.distance*100:a.mode.brake?(a.mode.from-(s?.speed||0))/a.mode.from*100:((s?.speed||0)-a.mode.from)/(a.mode.to-a.mode.from)*100):0)+'%';drawG($('#live-g'),s,d.trail,d.gap);}
function updateDevice(){const d=state.device;$('#device-link').textContent=state.connected?'Подключён · симуляция':'Нет связи';$('#connect-toggle').textContent=state.connected?'Отключиться':'Подключиться';$('#calibration-status').textContent=({idle:'Калибровка не запускалась',waiting:'Ожидание неподвижности…',running:'Калибровка выполняется…',success:'Калибровка завершена',error:'Ошибка: обнаружено движение. Повторите.'})[d.calibration];$('#command-state').textContent=state.pending?'Ожидание подтверждения прибора…':'Настройки подтверждены прибором';['brightness','sound','calibrate'].forEach(id=>$('#'+id).disabled=!state.connected||state.pending||(id==='calibrate'&&(locked()||['waiting','running'].includes(d.calibration))));$('#diag-gnss').textContent=d.gnss?'VALID':'INVALID';$('#diag-seq').textContent=d.sample?.sequence??'—';$('#diag-age').textContent=state.connected?`${Math.round((d.time-(d.sample?.time||0))*1000)} мс`:'Устаревший кадр';$('#diag-gap').textContent=d.gap?'Пропуск':'Поступает';}
function bindPage(){document.querySelectorAll('[data-nav]').forEach(button=>button.onclick=()=>navigate(button.dataset.nav));if(detailId){$('#back-history').onclick=()=>navigate('history');document.querySelectorAll('[data-segment]').forEach(button=>button.onclick=()=>{selectedSegment=button.dataset.segment||null;cursor=null;render(true);});document.querySelectorAll('[data-axis]').forEach(button=>button.onclick=()=>{if(button.disabled)return;chartAxis=button.dataset.axis;cursor=null;render(true);});document.querySelectorAll('[data-series-toggle]').forEach(button=>button.onclick=()=>{const key=button.dataset.seriesToggle;visibleSeries={...visibleSeries,[key]:!visibleSeries[key]};button.setAttribute('aria-pressed',String(visibleSeries[key]));updateDetail();});document.querySelectorAll('.performance-chart,.slope-chart').forEach(canvas=>{const seek=event=>{const box=canvas.getBoundingClientRect(),left=Number(canvas.dataset.plotLeft||0),right=Number(canvas.dataset.plotRight||box.width);cursor=Math.max(0,Math.min(1,(event.clientX-box.left-left)/Math.max(1,right-left)));updateDetail();};canvas.onpointerdown=event=>{canvas.focus();canvas.setPointerCapture(event.pointerId);seek(event);};canvas.onpointermove=event=>{if(event.buttons)seek(event);};canvas.onkeydown=event=>{if(!['ArrowLeft','ArrowRight','Home','End','Escape'].includes(event.key))return;event.preventDefault();if(event.key==='Escape')cursor=null;else if(event.key==='Home')cursor=0;else if(event.key==='End')cursor=1;else cursor=Math.max(0,Math.min(1,(cursor??.5)+(event.key==='ArrowRight'?.02:-.02)));updateDetail();};});}else if(page==='live'){$('#choose-car').onclick=showCars;$('#choose-mode').onclick=showModes;$('#trip-toggle').onclick=()=>command('trip');}else if(page==='history'){document.querySelectorAll('[data-history]').forEach(button=>button.onclick=()=>{historyTab=button.dataset.history;render(true);});$('#history-filter').value=filter;$('#history-filter').onchange=event=>{filter=event.target.value;render(true);};}else{$('#connect-toggle').onclick=()=>{adapter.connect(!adapter.connected);render(true);};$('#brightness').oninput=event=>$('#brightness-value').textContent=event.target.value+'%';$('#brightness').onchange=async event=>{await command('brightness',{value:event.target.value});render(true);};$('#sound').onchange=async event=>{await command('sound',{value:event.target.checked});render(true);};$('#calibrate').onclick=()=>command('calibrate');}document.querySelectorAll('[data-detail]').forEach(button=>button.onclick=()=>openDetail(button.dataset.detail));}
function updateCockpit(){const d=state.device,a=d.attempt,events=a?.events||[],recording=!!d.trip||!!(a&&a.start!==null&&a.phase!=='result');$('.dashboard').classList.add('auto-layout');$('#session-clock').textContent=recording?duration(a?.elapsed??d.trip?.duration??0):a?.phase==='result'?'Сохранено':'Готова';$('#recording-state').classList.toggle('recording',recording);$('#event-count').textContent=events.length?`${events.length} событий`:'';const eventKey=events.map(event=>event.recordId+':'+event.valid).join('|');if($('#event-feed').dataset.key!==eventKey){$('#event-feed').dataset.key=eventKey;$('#event-feed').innerHTML=events.slice().reverse().map(event=>`<div data-event-id="${esc(event.recordId)}" class="event-item ${event.valid?'':'invalid'}"><span>${esc(event.label)}</span><strong>${fmt(event.elapsed)} с</strong>${event.speed===null?'':`<small>${Math.round(event.speed)} км/ч</small>`}</div>`).join('');for(const el of $('#event-feed').children){if(!renderedEventIds.has(el.dataset.eventId)&&a?.phase!=='result')el.classList.add('event-new');renderedEventIds.add(el.dataset.eventId);}}const finish=$('#run-actions [data-action="cancel"]');if(finish)finish.textContent='Завершить и сохранить';}
function styleAutoEvents(){}
function autoEventText(event){styleAutoEvents();return `${event.label} · ${fmt(event.elapsed)} с${event.speed===null?'':` · ${Math.round(event.speed)} км/ч`}`;}
function updateAutoLive(){const d=state.device,a=d.attempt,s=d.sample,phase=a?.phase||'idle',last=a?.events?.at(-1);$('.dashboard').classList.toggle('measuring',!!a&&phase!=='result');$('#speed-value').textContent=s?s.speed.toFixed(1):'—';$('#time-value').textContent=fmt(a?.elapsed);$('#gnss-state').textContent=d.gnss?'GNSS готов':'GNSS недостоверен';$('#gnss-state').classList.toggle('bad',!d.gnss);$('#sat-state').textContent=`SV ${s?.satellites??'—'}`;$('#link-state').textContent=!state.connected?'Устаревший кадр':d.gap?'Нет данных':'Связь установлена';$('#phase-title').textContent=phase==='result'?'Заезд сохранён':a?.motionPhase||'Готов к старту';$('#phase-hint').textContent=phase==='conditions'||phase==='waiting'?'Остановитесь и начните разгон':a?.reasons?.length?a.reasons.join(' · '):last?`Последнее: ${autoEventText(last)}`:'Прибор сам определяет разгон, движение на скорости и торможение.';$('#phase-hint').classList.toggle('bad',!!a?.reasons?.length);if(last){const key=`${last.recordId}:${last.key}`;if(updateAutoLive.lastKey!==key){updateAutoLive.lastKey=key;if(d.settings.sound&&'speechSynthesis'in window){speechSynthesis.cancel();speechSynthesis.speak(new SpeechSynthesisUtterance(autoEventText(last)));}}}const box=$('#run-actions'),disabled=!state.connected||state.pending?'disabled':'',actionKey=`auto-${phase}-${state.connected}-${state.pending}`;if(box.dataset.key!==actionKey){box.dataset.key=actionKey;box.innerHTML=phase==='result'?`<button class="primary" data-action="arm" ${disabled}>Новый автозаезд</button><button data-action="dismiss" ${disabled}>К прибору</button>`:a?`<button class="primary" data-action="cancel" ${disabled}>Завершить заезд</button>`:`<button class="primary" data-action="arm" ${disabled||(!d.gnss||d.gap?'disabled':'')}>Готов к автозаезду</button>`;box.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>command(b.dataset.action));}$('#choose-car').disabled=locked()||!state.connected||state.pending;$('#choose-mode').disabled=active()||!state.connected||state.pending;$('#choose-car span').textContent=carName(d.carId)+' ▾';$('#choose-mode span').textContent=modeName(d.mode)+' ▾';$('#trip-title').textContent=d.trip?'Поездка записывается':'Запись поездки';$('#trip-clock').textContent=d.trip?duration(d.trip.duration):'Выключена';$('#trip-toggle').textContent=d.trip?'Остановить запись':'Начать запись';$('#trip-toggle').disabled=!state.connected||state.pending;$('#run-progress').style.width=phase==='result'?'100%':a?.motionPhase==='Торможение'?'78%':a?.motionPhase==='Движение на скорости'?'55%':a?.motionPhase==='Разгон'?'30%':'0%';drawG($('#live-g'),s,d.trail,d.gap);}
function updateManualLive(){const d=state.device,a=d.attempt,phase=a?.phase||'idle',s=d.sample;$('.dashboard').classList.toggle('measuring',!!a);$('#speed-value').textContent=s?s.speed.toFixed(1):'—';$('#time-value').textContent=fmt(a?.elapsed);$('#gnss-state').textContent=d.gnss?'GNSS готов':'GNSS недостоверен';$('#gnss-state').classList.toggle('bad',!d.gnss);$('#sat-state').textContent=`SV ${s?.satellites??'—'}`;$('#link-state').textContent=!state.connected?'Устаревший кадр':d.gap?'Нет данных':'Связь установлена';const text=phase==='conditions'?['Ожидание условий','Подготовьте автомобиль к старту']:phase==='waiting'?['Ожидание старта','Начните движение']:phase==='running'?['Замер идёт','Финиш определяет прибор']:phase==='result'?['Результат сохранён',a.valid?'Достоверный результат':a.reasons.join(' · ')]:['Готов к подготовке','Выберите ручной режим и подготовьте попытку'];$('#phase-title').textContent=text[0];$('#phase-hint').textContent=text[1];const box=$('#run-actions'),disabled=!state.connected||state.pending?'disabled':'',key=`manual-${phase}-${state.connected}-${state.pending}`;if(box.dataset.key!==key){box.dataset.key=key;box.innerHTML=phase==='result'?`<button class="primary" data-action="arm" ${disabled}>Повторить</button><button data-action="dismiss" ${disabled}>К прибору</button>`:a?`<button class="danger" data-action="cancel" ${disabled}>${phase==='running'?'Прервать попытку':'Отменить ожидание'}</button>`:`<button class="primary" data-action="arm" ${disabled||(!d.gnss||d.gap?'disabled':'')}>Готов к замеру</button>`;box.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>command(b.dataset.action));}$('#choose-car').disabled=locked()||!state.connected||state.pending;$('#choose-mode').disabled=active()||!state.connected||state.pending;$('#choose-car span').textContent=carName(d.carId)+' ▾';$('#choose-mode span').textContent=modeName(d.mode)+' ▾';$('#trip-title').textContent=d.trip?'Поездка записывается':'Запись поездки';$('#trip-clock').textContent=d.trip?duration(d.trip.duration):'Выключена';$('#trip-toggle').textContent=d.trip?'Остановить запись':'Начать запись';$('#trip-toggle').disabled=!state.connected||state.pending;$('#run-progress').style.width=phase==='result'?'100%':'0%';drawG($('#live-g'),s,d.trail,d.gap);}
function openDetail(id){const run=state.device.runs.find(r=>r.id===id);detailId=run?.auto?run.sessionId:id;selectedSegment=run?.auto?id:null;page='history';cursor=0;render(true);window.scrollTo({top:0,behavior:'smooth'});}
function sheet(title,body){const s=$('#sheet');s.innerHTML=`<header><h2>${title}</h2><button aria-label="Закрыть" id="close-sheet">×</button></header>${body}`;$('#close-sheet').onclick=()=>s.close();if(!s.open)s.showModal();}
function showCars(){sheet('Автомобиль',`<div class="stack"><button id="no-car">Без автомобиля</button>${state.device.cars.map(c=>`<div class="car-row"><button data-car="${c.id}">${esc(c.name)}</button><button data-rename="${c.id}" aria-label="Переименовать ${esc(c.name)}">Изменить</button></div>`).join('')}<form id="car-form" class="stack"><label>Новый автомобиль<input id="car-name" maxlength="60" required placeholder="Например, Golf GTI"></label><button class="primary">Добавить автомобиль</button></form><p class="hint">Выбор закрепляется за новыми поездками и замерами.</p></div>`);$('#no-car').onclick=async()=>{if(await command('car',{id:null}))$('#sheet').close();};document.querySelectorAll('[data-car]').forEach(b=>b.onclick=async()=>{if(await command('car',{id:b.dataset.car}))$('#sheet').close();});document.querySelectorAll('[data-rename]').forEach(b=>b.onclick=()=>{const car=state.device.cars.find(c=>c.id===b.dataset.rename);sheet('Название автомобиля',`<form id="rename-form" class="stack"><label>Название<input id="rename-name" value="${esc(car.name)}" maxlength="60" required></label><button class="primary">Сохранить</button></form>`);$('#rename-form').onsubmit=async e=>{e.preventDefault();if(await command('renameCar',{id:car.id,name:$('#rename-name').value}))showCars();};});$('#car-form').onsubmit=async e=>{e.preventDefault();if(await command('addCar',{name:$('#car-name').value}))showCars();};}
function showModes(){sheet('Выберите замер',`<div class="mode-list">${MODES.filter(m=>m.id!=='custom').map(m=>`<button data-mode="${m.id}">${m.name}</button>`).join('')}</div><form id="custom-mode" class="stack" style="margin-top:18px"><h3>Свой диапазон разгона</h3><div class="row"><label class="grow">От, км/ч<input id="from" type="number" min="0" max="299" value="60" required></label><label class="grow">До, км/ч<input id="to" type="number" min="1" max="300" value="120" required></label></div><button class="primary">Выбрать диапазон</button></form>`);document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=async()=>{if(await command('mode',{mode:MODES.find(m=>m.id===b.dataset.mode)}))$('#sheet').close();});$('#custom-mode').onsubmit=async e=>{e.preventDefault();if(await command('mode',{mode:{id:'custom',name:'Свой диапазон',from:+$('#from').value,to:+$('#to').value}}))$('#sheet').close();};}
function context(canvas){const r=canvas.getBoundingClientRect(),dpr=window.devicePixelRatio||1,w=r.width,h=r.height;if(canvas.width!==Math.round(w*dpr)||canvas.height!==Math.round(h*dpr)){canvas.width=Math.round(w*dpr);canvas.height=Math.round(h*dpr);}const c=canvas.getContext('2d');c.setTransform(dpr,0,0,dpr,0,0);c.clearRect(0,0,w,h);return {c,w,h};}
function drawG(canvas,s,trail=[],gap=false){if(!canvas)return;if(canvas.id==='live-g'&&document.body.classList.contains('live-theme'))return drawLiveG(canvas,s,trail,gap);const {c,w,h}=context(canvas),r=w*.46,x=w/2,y=h/2,point=sample=>gCirclePoint(sample,x,y,r);c.strokeStyle='#687582';c.lineWidth=1;c.beginPath();c.arc(x,y,r,0,Math.PI*2);c.stroke();c.strokeStyle='#35414d';c.setLineDash([3,5]);c.beginPath();c.arc(x,y,r/2,0,Math.PI*2);c.stroke();c.beginPath();c.moveTo(x-r,y);c.lineTo(x+r,y);c.moveTo(x,y-r);c.lineTo(x,y+r);c.stroke();c.setLineDash([]);c.fillStyle='#9aa6b4';c.font='12px Segoe UI';c.fillText('1 g',x+5,y-r+15);c.fillStyle='#f1f3f6';c.font='700 11px Segoe UI';c.textAlign='center';c.fillText('0 g',x,y-10);c.textAlign='left';c.fillStyle='#0d1014';c.beginPath();c.arc(x,y,6,0,Math.PI*2);c.fill();c.strokeStyle='#f1f3f6';c.lineWidth=2;c.beginPath();c.moveTo(x-5,y);c.lineTo(x+5,y);c.moveTo(x,y-5);c.lineTo(x,y+5);c.stroke();c.strokeStyle='#ffa94b';c.lineWidth=2;const visibleTrail=s?trail.filter(item=>s.time-item.time<=1):trail;for(let i=1;i<visibleTrail.length;i++){if(visibleTrail[i].time-visibleTrail[i-1].time>.15)continue;c.globalAlpha=i/visibleTrail.length*.6;c.beginPath();c.moveTo(...point(visibleTrail[i-1]));c.lineTo(...point(visibleTrail[i]));c.stroke();}c.globalAlpha=gap?.25:1;if(s){const [px,py]=point(s),magnitude=Math.hypot(s.lateral,s.longitudinal),color=magnitude>1?'#ff837e':'#7adab1';c.strokeStyle=color;c.lineWidth=1.5;c.setLineDash([4,4]);c.beginPath();c.moveTo(x,y);c.lineTo(px,py);c.stroke();c.setLineDash([]);c.fillStyle=color;c.shadowColor=color;c.shadowBlur=14;c.beginPath();c.arc(px,py,6,0,Math.PI*2);c.fill();c.shadowBlur=0;canvas.parentElement.querySelector('[data-g-lat]').textContent=signed(s.lateral);canvas.parentElement.querySelector('[data-g-long]').textContent=signed(s.longitudinal);}else{canvas.parentElement.querySelector('[data-g-lat]').textContent='—';canvas.parentElement.querySelector('[data-g-long]').textContent='—';}c.globalAlpha=1;}
function slopeReadout(sample){if(Number.isFinite(sample.slopePercent))return 'Уклон '+fmt(sample.slopePercent)+'%';if(Number.isFinite(sample.provisionalSlopePercent))return 'Уклон ~'+fmt(sample.provisionalSlopePercent)+'% · сбор данных';return 'Сбор данных для уклона';}
function updateDetail(){const ctx=detailContext();if(!ctx||!ctx.samples.length)return;const profile=roadProfile(ctx.samples),xKey=chartAxis==='distance'?'distanceM':'time',main=$('#performance-chart'),slope=$('#slope-chart');if(profile.hasAltitude){slope.classList.remove('is-hidden');document.querySelector('.slope-unavailable')?.remove();}const report=drawPerformanceReport({mainCanvas:main,slopeCanvas:slope,samples:ctx.samples,profilePoints:profile.points,xKey,visible:visibleSeries,cursor});if(cursor===null){$('#cursor-time').textContent='Коснитесь графика';$('#cursor-distance').textContent='';$('#cursor-speed').textContent='Скорость —';$('#cursor-long').textContent='Ускорение —';$('#cursor-alt').textContent='Высота —';$('#cursor-slope').textContent='Уклон —';$('#cursor-gap').textContent='';return;}const current=report.cursor;if(!current||current.hasGap||!current.sample){$('#cursor-time').textContent='Нет данных';$('#cursor-gap').textContent='В этой точке нет образца';return;}const sample=current.sample,first=ctx.samples[0],rel=sample.relativeAltitudeM;$('#cursor-time').textContent=fmt(sample.time-first.time)+' с';$('#cursor-distance').textContent=Number.isFinite(sample.distanceM)?Math.round(sample.distanceM-(first.distanceM||0))+' м':'';$('#cursor-speed').textContent='Скорость '+sample.speed.toFixed(1)+' км/ч';$('#cursor-long').textContent='Ускорение '+signed(sample.longitudinal);$('#cursor-alt').textContent=Number.isFinite(rel)?'Высота '+fmt(sample.altitudeMslM)+' м · '+fmt(rel)+' м':'Высота —';$('#cursor-slope').textContent=slopeReadout(sample);$('#cursor-gap').textContent='';}
document.querySelectorAll('[data-demo]').forEach(b=>b.onclick=()=>{switch(b.dataset.demo){case'drive':if(!device.attempt||!['conditions','waiting'].includes(device.attempt.phase)){toast('Сначала нажмите «Готов к замеру» на приборной панели.');return;}device.gnss=true;device.gap=false;device.startDrive();toast('Демонстрационная поездка началась.');break;case'gnss':device.gnss=!device.gnss;b.textContent=device.gnss?'Ухудшить GNSS':'Восстановить GNSS';break;case'link':adapter.connect(!adapter.connected);b.textContent=adapter.connected?'Потерять связь':'Восстановить связь';break;case'gap':device.gap=!device.gap;b.textContent=device.gap?'Восстановить поток':'Разрыв телеметрии';break;case'fail':adapter.failNext=true;toast('Следующая команда завершится ошибкой.');break;case'cal-fail':device.failCalibration=true;toast('Следующая калибровка завершится ошибкой.');break;}adapter.publish();});
$('#drive-speed').oninput=e=>{device.drive=null;device.manualSpeed=+e.target.value;$('#manual-speed').textContent=e.target.value+' км/ч';};
$('#page').addEventListener('click',event=>{const button=event.target.closest('#run-actions [data-action]');if(!button||!(state.device.attempt?.mode||state.device.mode).auto)return;event.stopImmediatePropagation();if(!button.disabled)command(button.dataset.action);},true);
function announceMilestones(){const a=state.device.attempt;if(!a?.milestones)return;for(const item of a.milestones){const key=`${a.id}:${item.speed}`;if(announcedMilestones.has(key))continue;announcedMilestones.add(key);const phrase=`${item.speed} километров в час. ${fmt(item.elapsed)} секунды`;toast(`${item.speed} км/ч · ${fmt(item.elapsed)} с`);if('speechSynthesis'in window){speechSynthesis.cancel();speechSynthesis.speak(new SpeechSynthesisUtterance(phrase));}}}
adapter.subscribe(s=>{state=s;announceMilestones();render();});
let lastSave='';setInterval(()=>{adapter.tick(.05);const k=`${device.runs.length}:${device.trips.length}:${device.autoSessions.length}`;if(k!==lastSave){lastSave=k;persist();}},50);
window.addEventListener('resize',()=>render());
window.addEventListener('pagehide',()=>{const a=device.attempt;if(a&&['conditions','waiting','running'].includes(a.phase)){if(a.mode.auto&&a.start!==null)device.finishAuto('Демонстрация закрыта до завершения');else if(!a.mode.auto)device.finish('Демонстрация закрыта до завершения');}if(device.trip)device.command('trip');persist();});
function speedometerMarkup(){
  const point=(angle,r)=>[100+Math.sin(angle*Math.PI/180)*r,100-Math.cos(angle*Math.PI/180)*r];
  const ticks=Array.from({length:51},(_,i)=>{
    const angle=-135+i*5.4,major=i%10===0,medium=i%2===0,[x1,y1]=point(angle,major?77:medium?81:85),[x2,y2]=point(angle,90);
    const [tx,ty]=point(angle,66);
    return `<line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" class="${major?'major':medium?'medium':'minor'}"/>${major?`<text x="${tx}" y="${ty}" dy=".35em">${i*5}</text>`:''}`;
  }).join('');
  return `<svg class="speed-scale" viewBox="0 0 200 200" aria-hidden="true"><defs><radialGradient id="dial-surface"><stop class="dial-surface-center"/><stop class="dial-surface-edge" offset="1"/></radialGradient></defs><circle cx="100" cy="100" r="92" class="dial-rim"/><path class="speed-track" d="M 32.12 167.88 A 96 96 0 1 1 167.88 167.88"/><path id="speed-arc" class="speed-arc" pathLength="100" stroke-dasharray="100" stroke-dashoffset="100" d="M 32.12 167.88 A 96 96 0 1 1 167.88 167.88"/>${ticks}<g id="speed-needle" transform="rotate(-135 100 100)"><path class="needle-body" d="M 98.5 54 L 99 13 L 101 13 L 101.5 54 Z"/><path class="needle-tip" d="M 98 21 L 100 9 L 102 21 Z"/></g></svg>`;
}
function updateInstruments(){
  $('.screen').classList.toggle('large-text',parseFloat(getComputedStyle(document.documentElement).fontSize)>20);
  const s=state.device.sample,needle=$('#speed-needle');
  if(needle)needle.setAttribute('transform',`rotate(${-135+Math.max(0,Math.min(250,s?.speed||0))/250*270} 100 100)`);
  const fraction=Math.max(0,Math.min(250,s?.speed||0))/250;
  $('#speed-arc').setAttribute('stroke-dashoffset',String(100-fraction*100));
  const missing=!s||!Number.isFinite(s.speed);
  needle.style.visibility=missing?'hidden':'';
  $('#speed-arc').style.visibility=missing?'hidden':'';
  if(missing)$('#speed-value').textContent='—';
  $('.gauge-grid').classList.toggle('stale',!state.connected||state.device.gap||!state.device.gnss);
  $('#link-state').classList.toggle('bad',!state.connected);
  $('#link-state').classList.toggle('warning',state.connected&&state.device.gap);
  $('.dashboard').classList.toggle('auto-layout',!!(state.device.attempt?.mode||state.device.mode).auto);
}
function drawLiveG(canvas,s,trail,gap){
  const {c,w,h}=context(canvas),r=w*.46,x=w/2,y=h/2;
  const theme=getComputedStyle(canvas),color=name=>theme.getPropertyValue(name).trim();
  const point=sample=>gCirclePoint(sample,x,y,r);
  const surface=c.createRadialGradient(x,y,0,x,y,r);
  surface.addColorStop(0,color('--panel'));surface.addColorStop(1,color('--dial-edge'));
  c.fillStyle=surface;c.beginPath();c.arc(x,y,r,0,Math.PI*2);c.fill();
  c.strokeStyle=color('--instrument-line');c.lineWidth=1;c.stroke();
  c.setLineDash([2,5]);c.beginPath();c.arc(x,y,r/2,0,Math.PI*2);c.stroke();
  c.beginPath();c.moveTo(x-r,y);c.lineTo(x+r,y);c.moveTo(x,y-r);c.lineTo(x,y+r);c.stroke();c.setLineDash([]);
  c.fillStyle=color('--muted');c.font='400 12px "Golos Text", sans-serif';c.fillText('1 g',x+6,y-r+16);
  c.textAlign='center';c.fillStyle=color('--text');c.fillText('0 g',x,y-12);c.textAlign='left';
  c.strokeStyle=color('--accent');c.lineWidth=2;
  const recent=s?trail.filter(item=>s.time-item.time<=1):[];
  for(let i=1;i<recent.length;i++){
    if(recent[i].time-recent[i-1].time>.15)continue;
    c.globalAlpha=i/recent.length*.55;c.beginPath();c.moveTo(...point(recent[i-1]));c.lineTo(...point(recent[i]));c.stroke();
  }
  c.globalAlpha=gap?.35:1;
  if(s){
    const [px,py]=point(s),ink=color(Math.hypot(s.lateral,s.longitudinal)>1?'--red':'--accent');
    c.strokeStyle=ink;c.lineWidth=1.5;c.beginPath();c.moveTo(x,y);c.lineTo(px,py);c.stroke();
    c.fillStyle=ink;c.beginPath();c.arc(px,py,4.5,0,Math.PI*2);c.fill();
  }
  c.globalAlpha=1;c.strokeStyle=color('--text');c.lineWidth=1.5;c.beginPath();c.arc(x,y,3,0,Math.PI*2);c.stroke();
  c.beginPath();c.moveTo(x-6,y);c.lineTo(x-3,y);c.moveTo(x+3,y);c.lineTo(x+6,y);c.moveTo(x,y-6);c.lineTo(x,y-3);c.moveTo(x,y+3);c.lineTo(x,y+6);c.stroke();
  canvas.parentElement.querySelector('[data-g-lat]').textContent=s?signed(s.lateral):'—';
  canvas.parentElement.querySelector('[data-g-long]').textContent=s?signed(s.longitudinal):'—';
}
